CREATE TABLE allowlist (email VARCHAR(254) PRIMARY KEY, role ENUM('sales','owner') NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE config_prices (name VARCHAR(80) PRIMARY KEY, amount DECIMAL(12,2) NOT NULL);
CREATE TABLE config_stages (name VARCHAR(80) PRIMARY KEY, sort_order INT NOT NULL, managed_only BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE config_stop_conditions (id INT AUTO_INCREMENT PRIMARY KEY, label VARCHAR(200) NOT NULL UNIQUE, status VARCHAR(30) NOT NULL DEFAULT 'TODO-OWNER');
CREATE TABLE config_discovery (id VARCHAR(20) PRIMARY KEY, definition JSON NOT NULL);
CREATE TABLE prospects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, business_name VARCHAR(255) NOT NULL, contact_name VARCHAR(255) NOT NULL DEFAULT '', phone VARCHAR(80) NOT NULL DEFAULT '', email VARCHAR(254) NOT NULL DEFAULT '', first_contact DATE NULL, employee_count INT UNSIGNED NULL, current_it TEXT NOT NULL, key_dependency TEXT NOT NULL, call_frequency VARCHAR(40) NOT NULL DEFAULT 'Not sure', likely_tier VARCHAR(80) NOT NULL DEFAULT 'Not sure', red_flag VARCHAR(255) NOT NULL DEFAULT '', stage VARCHAR(80) NOT NULL DEFAULT 'Prospecting', follow_up DATE NULL, notes TEXT NOT NULL, owner VARCHAR(254) NOT NULL DEFAULT 'alanna@theitguys.us', service_lane VARCHAR(80) NULL, client_id VARCHAR(80) NULL, client_item_id VARCHAR(80) NULL, hold BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE activities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, prospect_id BIGINT UNSIGNED NOT NULL, type ENUM('call','visit','email','note') NOT NULL, outcome VARCHAR(100) NOT NULL, notes TEXT NOT NULL, occurred_on DATE NOT NULL, actor VARCHAR(254) NOT NULL, FOREIGN KEY (prospect_id) REFERENCES prospects(id));
CREATE TABLE weekly_imports (week_start DATE PRIMARY KEY, calls INT UNSIGNED NOT NULL, conversations INT UNSIGNED NOT NULL, qualified INT UNSIGNED NOT NULL, proposals INT UNSIGNED NOT NULL, recurring INT UNSIGNED NOT NULL, hourly INT UNSIGNED NOT NULL);
CREATE TABLE imports (kind VARCHAR(30) PRIMARY KEY, actor VARCHAR(254) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE discoveries (prospect_id BIGINT UNSIGNED PRIMARY KEY, answers JSON NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'Draft', revision INT NOT NULL DEFAULT 0, flags JSON NOT NULL, FOREIGN KEY (prospect_id) REFERENCES prospects(id));
CREATE TABLE discovery_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, prospect_id BIGINT UNSIGNED NOT NULL, revision INT NOT NULL, answers JSON NOT NULL, actor VARCHAR(254) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY version_key (prospect_id,revision));
CREATE TABLE quotes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, prospect_id BIGINT UNSIGNED NOT NULL, inputs JSON NOT NULL, line_items JSON NOT NULL, total DECIMAL(12,2) NOT NULL, status ENUM('Draft','Approved','Sent') NOT NULL DEFAULT 'Draft', approved_by VARCHAR(254) NULL, approved_at DATETIME NULL, stop_review JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (prospect_id) REFERENCES prospects(id));
CREATE TABLE sp_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, prospect_id BIGINT UNSIGNED NOT NULL, action VARCHAR(80) NOT NULL, request_json JSON NOT NULL, item_id VARCHAR(80) NULL, status VARCHAR(40) NOT NULL, result_message TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (prospect_id) REFERENCES prospects(id));
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, prospect_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(40) NOT NULL, message_json JSON NOT NULL, status VARCHAR(40) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor VARCHAR(254) NOT NULL, action VARCHAR(100) NOT NULL, entity VARCHAR(80) NOT NULL, entity_id VARCHAR(80) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);

